from __future__ import print_function
import logging


def docstring_parameter(*sub):
    """Decorator allowing formatted docstrings"""
    def _fun_with_formated_docstring(obj):
        obj.__doc__ = obj.__doc__.format(*sub)
        return obj
    return _fun_with_formated_docstring


plugin_usage = """
ta_ue_plugin_android doesn't work standalone - it is plugin. You need ute_ue first:
pip install ute_ue
Then ensure plugin is installed as well:
pip install ta_ue_plugin_android
pip list | grep ute-ue
"""

plugin_info = """
Android implementation of Abstract UE (ute_ue library).

This version of plugin supports following functionality:
    - Require Ue keyword to take ue into use from available ues
    - Attach and Detach for UE
    - Data Transfer handling (start, stop and verify throughput)
    - Start Voice Call, Stop Voice Call, Await Voice Call Finish
        - From Android 6.0 mobile application should be configured as a default android dialer.
          The instructions how to configure it can be found on the hints page:
          https://confluence.int.net.nokia.com/display/LTEVERTA/04.+UE+Manager+hints
    - Change Network Mode,
    - Send SMS, Receive SMS,
    - Turn Wifi On, Turn Wifi Off,
    - Merge Into Conference (available from Android 6.0),
    - Hold Voice Call, Retrieve Voice Call (available from Android 6.0),
    - Start Recording Voice, Stop Recording Voice (rooted ue required, UE Manager Mobile or NAA should be installed as a android system application),
    - Send DTMF,
    - Support for HTTP and FTP protocols in Start Data Transfer (busybox application required on android),
    - Video Calls:
        - new parameter added to Start Voice Call: with_video,
        - new parameter's "action" value added to Await Incoming Voice Call: answer_with_video,
        - new keywords: Upgrade To Video Call, Downgrade To Voice Call,
    - Keywords not yet added to the official ute_ue interface,
      currently available via Android custom keywords and proxy behind facade feature (TAUE-4):
        - Get Info - possibility to read details like: Cell ID, IP, PCI, MCC, MNC, Signal Strength,
        - Start / Stop RRC Logs (rooted UE required),
        - Reboot UE,
        - Restart Mobile Application,
        - Call Forwarding / Call Waiting / Call Barring - available via USSD codes which can be sent by Start Voice Call,

Ue types that are currently supported:
    - Android UEs with UE Manager or NAA application installed:
        - https://confluence.ext.net.nokia.com/display/AbstractLibs/NAA+-+Nokia+Android+Application
        - This solution should work on any android UE with any Android version however there are some models which have been verified by our team:
            - https://confluence.int.net.nokia.com/display/LTEVERTA/13.+Tested+UEs
    - Qualcomm prototypes controlled by AT commands,
        - Will be extracted to separate ute_ue / ute_ue plugin in the future,
    - Other UEs controlled by AT commands like Nimbelink/Sequans/Sierra.

development project and code repository: https://wrgitlab.int.net.nokia.com/abstract_library/ta_ue_plugin_android

ute_ue JIRA: https://jiradc.int.net.nokia.com/projects/TAUE

ute_ue wiki: https://wrgitlab.int.net.nokia.com/abstract_library/ute_ue/wikis/home

ute_ue Confluence: https://confluence.int.net.nokia.com/display/AbstractLibs/ute_ue

developers mailing list: I_ABSTRACT_LIBRARY_DEV@internal.nsn.com, ue-manager-developers@list.nokia.com

Ue configuration may be given either as robot variable or environment variable - details see ute_ue documentation.

Android configuration file examples: see ta_ue_plugin_android/example/config/ folder
or search ta_ue_plugin_android repository for *.yml files

Test Cases examples are available in:
    - ute_ue/example/
    - ta_ue_plugin_android/example/
"""


class ta_ue_plugin_android(object):
    """Android implementation of Abstract UE (ute_ue library)"""

    ROBOT_LIBRARY_SCOPE = 'GLOBAL'

    @docstring_parameter(plugin_usage)
    def show_plugin_usage(self):
        """
        Put into logs usage of this plugin:

        {}

        :return: usage string
        """
        logger = logging.getLogger('ute_ue')
        logger.warning(plugin_usage)
        return plugin_usage

    @docstring_parameter(plugin_info)
    def show_plugin_info(self):
        """
        Put into logs information about this plugin:

        {}

        :return: information string
        """
        logger = logging.getLogger('ute_ue')
        logger.warning(plugin_info)
        return plugin_info


if __name__ == '__main__':
    plugin = ta_ue_plugin_android()
    print(plugin.show_plugin_usage())
    print("------------------------------------")
    print(plugin.show_plugin_info())
    print("------------------------------------")
